import{_ as r,l as o,o as a,c as l,v as t,p as s,x as i,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"HTTP/1.1 持久连接与分块","description":"","frontmatter":{"title":"HTTP/1.1 持久连接与分块","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/http11-persistent-chunked.md","filePath":"cs/http11-persistent-chunked.md","lastUpdated":1789023840000}'),c={name:"cs/http11-persistent-chunked.md"};function T(u,e,_,k,P,f){const n=o("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="http-1-1-持久连接与分块" tabindex="-1">HTTP/1.1 持久连接与分块 <a class="header-anchor" href="#http-1-1-持久连接与分块" aria-label="Permalink to &quot;HTTP/1.1 持久连接与分块&quot;">​</a></h1><div class="epigraph"><p>默认保持 TCP 连接复用多个请求；长度未知时用 chunked 编码分块结束，而不再靠关闭连接当 EOF。</p><footer>—— 据 RFC 9112 HTTP/1.1；RFC 2616 历史对照整理</footer></div><p>主干<a href="/cs/http">HTTP</a> 给语义。<a href="/cs/tcp-wireless">上一课</a> 结束传输进阶。缺口是 <strong>1.1 怎么把消息映到字节流</strong>：Connection: keep-alive 成默认、Content-Length vs chunked。本课不把队头阻塞写完，下一课写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HTTP/1.0 常一请求一连接，握手与慢启动税重。<a href="/cs/bandwidth-delay-product">BDP</a> 刚填满就拆。1.1：持久连接上串行请求；报文体要么事先长度，要么 <code>Transfer-Encoding: chunked</code> 用 0 块结束。管道化（pipelining）允许一次排多个请求，但响应必须顺序——HOL 下一课。分块让动态页面不必先算全长。</p><p>不要把持久连接写成 TCP keepalive。</p><p><span class="marginnote">RFC 9112。chunk 大小十六进制。本课不把废弃的 identity 编码展开。</span></p><h3 id="不是-tcp-keepalive" tabindex="-1">不是 TCP keepalive <a class="header-anchor" href="#不是-tcp-keepalive" aria-label="Permalink to &quot;不是 TCP keepalive&quot;">​</a></h3><p>持久连接摊销握手。chunked 提供无先验长度的成帧。管道化顺序响应，现实常关。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：握手一次 → 多请求 → 长度或分块。对照 TSO：大 write 仍是一请求体。与 MSS 无关直接，但小请求头税相对大。</p>',11)),(a(),s(h,null,{default:i(()=>[d(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TCP%5B%22%E4%B8%80%E6%9D%A1%20TCP%22%5D%20--%3E%20R1%5B%22%E8%AF%B7%E6%B1%82%201%22%5D%0A%20%20R1%20--%3E%20R2%5B%22%E8%AF%B7%E6%B1%82%202%22%5D%0A%20%20BODY%5B%22%E6%AD%A3%E6%96%87%22%5D%20--%3E%20CL%5B%22Content-Length%22%5D%0A%20%20BODY%20--%3E%20CH%5B%22chunked%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>中间代理必须理解分块才能复用连接。TLS 入口在持久连接上摊销握手，动机与 QUIC 1-RTT 同类但层不同。无线掉线后半开，1.1 连接死，应用重开。SYN cookies 只影响新握手次数，持久化减少握手。</p><p>安全：未授权的连接复用要把认证绑对（后课 Cookie）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 HTTP/1.1 升级头的全部。队头阻塞对照是下一课。后课默认：1.1 默认持久；未知长度用分块。</p><p>管道化在现实中常关，因 HOL 与坏代理。</p><p>上一课留下的缺口在本课收口；「HTTP/1.1 持久连接与分块」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/hol-blocking">队头阻塞对照</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>持久连接摊销握手与慢启动。</li><li>chunked 提供无先验长度的成帧。</li><li>管道化顺序响应，HOL 留给下一课。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9112。</li></ul>',10))])}const b=r(c,[["render",T]]);export{C as __pageData,b as default};
